import {expect,test}from"@playwright/test";
async function handle(page:any){return page.evaluateHandle(()=>{const host=document.querySelector(".drum-kit-canvas") as any,key=Object.keys(host).find(k=>k.startsWith("__reactFiber"));let f=host[key],r=f;while(r.return)r=r.return;const seen=new Set<any>();let found:any;const walk=(n:any):void=>{if(!n||seen.has(n)||found)return;seen.add(n);if(String(n.type?.render?.name||n.type?.name||"").includes("DrumKitCanvas")){let h=n.memoizedState;while(h){if(h.memoizedState?.current?.snapshot)found=h.memoizedState.current;h=h.next}}walk(n.child);walk(n.sibling)};walk(r);return found})}
test("diagnose practice hit state",async({page})=>{await page.setViewportSize({width:844,height:340});await page.goto("/practice");await expect(page.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status","ready");await page.getByRole("button",{name:"Start 4-count"}).click();await expect(page.locator(".mode-pill")).toHaveText("count-in");await page.evaluate(()=>window.advanceTime?.(4200));await expect(page.locator(".mode-pill")).toHaveText("playing");const before=await page.evaluate(()=>window.render_game_to_text?.());await page.keyboard.press("f");const immediate=await page.evaluate(()=>window.render_game_to_text?.());await page.waitForTimeout(95);const at95=await page.evaluate(()=>window.render_game_to_text?.());await page.locator("canvas").screenshot({path:"output/playwright/drum-model-qa-licensed-v3-diagnostic/contact-95ms.png"});await page.waitForTimeout(50);const at145=await page.evaluate(()=>window.render_game_to_text?.());await page.locator("canvas").screenshot({path:"output/playwright/drum-model-qa-licensed-v3-diagnostic/rebound-145ms.png"});const handles=await page.evaluate(()=>{const host=document.querySelector(".drum-kit-canvas") as any;const fiberKey=Object.keys(host).find(k=>k.startsWith("__reactFiber"));let f=host?.[fiberKey as any],root=f;while(root?.return)root=root.return;const seen=new Set<any>(),out:any[]=[];const walk=(node:any)=>{if(!node||seen.has(node))return;seen.add(node);if(String(node.type?.render?.name||node.type?.name||node.elementType?.name||"").includes("DrumKitCanvas")){let h=node.memoizedState;while(h){const v=h.memoizedState;if(v?.current&&typeof v.current.snapshot==="function")out.push(v.current.snapshot());h=h.next}}walk(node.child);walk(node.sibling)};walk(root);return {fiberKey:Boolean(fiberKey),snapshots:out}});console.log(JSON.stringify({before,immediate,at95,at145,handles}));expect(String(immediate)).toContain("snare")});
test("deterministic wrapper advance renders a distinct strike",async({page})=>{await page.setViewportSize({width:844,height:340});await page.goto("/practice");await expect(page.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status","ready");const h=await handle(page);const start=await h.evaluate((x:any)=>x.snapshot());await h.evaluate((x:any)=>x.hit("snare"));const immediate=await h.evaluate((x:any)=>x.snapshot());await h.evaluate((x:any)=>x.advance(95));const contact=await h.evaluate((x:any)=>x.snapshot());await page.locator("canvas").screenshot({path:"output/playwright/drum-model-qa-licensed-v3-diagnostic/direct-contact-95ms.png"});await h.evaluate((x:any)=>x.advance(50));const rebound=await h.evaluate((x:any)=>x.snapshot());await page.locator("canvas").screenshot({path:"output/playwright/drum-model-qa-licensed-v3-diagnostic/direct-rebound-145ms.png"});console.log(JSON.stringify({start,immediate,contact,rebound}));expect(immediate.lastHit.instrument).toBe("snare");expect(contact.activeHits.length).toBeGreaterThan(0)});
